/* @lc app=leetcode id=2141 lang=kotlin */ class Solution { fun maxRunTime(n: Int, batteries: IntArray): Long = generateSequence(Triple(0L, batteries.sumOf { it.toLong() } / n, 0L)) { (l, r, ans) -> if (l <= r) ((l + r) / 2).let { mid -> if (batteries.fold(0L) { a, b -> a + minOf(b.toLong(), mid) } >= n.toLong() * mid) Triple(mid + 1, r, mid) else Triple(l, mid - 1, ans) } else null }.last().third }